import{_ as e,o as n,c as a,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse(`{"title":"A–Z lesson grouping: Web3 and Blockchain","description":"Draft for Sherwin's design review and Sean's authored lesson copy. Owner direction on October 28, 2026: each of the encyclopedia's 26 letters becomes one lesson, with 13 prima","frontmatter":{"title":"A–Z lesson grouping: Web3 and Blockchain","description":"Draft for Sherwin's design review and Sean's authored lesson copy. Owner direction on October 28, 2026: each of the encyclopedia's 26 letters becomes one lesson, with 13 prima","source":"docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-lesson-grouping-draft.md","category":"Archive","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-lesson-grouping-draft.md","filePath":"content/docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-lesson-grouping-draft.md"}`),r={name:"content/docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-lesson-grouping-draft.md"};function i(d,t,s,c,l,h){return n(),a("div",null,[...t[0]||(t[0]=[o('<div><h1 id="az-lesson-grouping-web3-and-blockchain">A–Z lesson grouping: Web3 and Blockchain<a class="header-anchor" href="#az-lesson-grouping-web3-and-blockchain" aria-label="Link to this section">​</a></h1><p>Draft for Sherwin&#39;s design review and Sean&#39;s authored lesson copy. Owner direction on October 28, 2026: each of the encyclopedia&#39;s 26 letters becomes one lesson, with <strong>13 primary lessons in Web3 and 13 in Blockchain</strong>. This draft recommends <strong>6 mini-game lessons and 20 quiz lessons</strong>. This is a full-curriculum structure, not a claim that 26 lessons are implemented, tested, school-approved, or required for the November 10 beta. The November 21 pre-final date and integration, QA, manuscript, and rehearsal time remain protected.</p><p>The <a href="/Chainy-Docs/content/docs/archive/source-material/web3-young-learners-encyclopedia-a-z-contents.html">source contents</a> preserve the book&#39;s original A–Z order and PDF page references. A letter&#39;s primary world is its main teaching location, not a ban on introducing the idea elsewhere. The existing Web3 purchase may introduce fees, keys, and ownership before their deeper Blockchain lessons. Mini-games below are <strong>recommendations</strong>, not approved mechanics or completed work. A mini-game can be a bounded interaction within a quest; it need not be a new standalone system.</p><h2 id="web3-world--13-letters">Web3 world — 13 letters<a class="header-anchor" href="#web3-world--13-letters" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Letter</th><th>Source chapter (PDF page)</th><th>Lesson focus</th><th>Suggested format</th></tr></thead><tbody><tr><td>A</td><td>Altcoins (8)</td><td>Recognize that digital coins can have different purposes.</td><td>Quiz</td></tr><tr><td>C</td><td>Cryptocurrency (10)</td><td>Budget fictional coins for the lantern purchase without treating them as real money.</td><td>Mini-game: review a fictional purchase</td></tr><tr><td>E</td><td>Exchanges (12)</td><td>Identify what an exchange does without using one.</td><td>Quiz</td></tr><tr><td>F</td><td>Fiat Currency (13)</td><td>Distinguish government-issued money from fictional game currency and cryptocurrency.</td><td>Quiz</td></tr><tr><td>H</td><td>HODL (15)</td><td>Recognize slang without presenting holding as financial advice.</td><td>Quiz</td></tr><tr><td>I</td><td>Identity and Online Safety (16)</td><td>Choose which personal details should stay private.</td><td>Quiz</td></tr><tr><td>J</td><td>Jupiter (JUP) (17)</td><td>Recognize a named swap service as an example, not a required tool.</td><td>Quiz</td></tr><tr><td>Q</td><td>QR Codes in Web3 (24)</td><td>Decide whether an unknown code or link is safe to open.</td><td>Quiz; no real scanning</td></tr><tr><td>R</td><td>Risks, Red Flags &amp; Staying Scam-Safe (25)</td><td>Spot a suspicious fictional request and explain the warning sign.</td><td>Mini-game: scam-spotting choices</td></tr><tr><td>U</td><td>Understanding Web3 Safety (28)</td><td>Apply a safe-use rule to a new situation.</td><td>Quiz</td></tr><tr><td>V</td><td>Volatility (29)</td><td>Explain why a changing price makes a purchase or promise risky.</td><td>Quiz</td></tr><tr><td>W</td><td>Wallets (30)</td><td>Inspect a fictional balance, item, and activity entry to answer a transaction question.</td><td>Mini-game: wallet inspection</td></tr><tr><td>X</td><td>XRP (31)</td><td>Recognize a named cryptocurrency as an example, without promoting it.</td><td>Quiz</td></tr></tbody></table><h2 id="blockchain-world--13-letters">Blockchain world — 13 letters<a class="header-anchor" href="#blockchain-world--13-letters" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Letter</th><th>Source chapter (PDF page)</th><th>Lesson focus</th><th>Suggested format</th></tr></thead><tbody><tr><td>B</td><td>Blockchain (9)</td><td>Link records to a trusted checkpoint and explain what the link checks.</td><td>Mini-game: bounded block sequence</td></tr><tr><td>D</td><td>Decentralization (11)</td><td>Distinguish one local copy from agreement among separate participants.</td><td>Quiz</td></tr><tr><td>G</td><td>Gas Fees (14)</td><td>Explain why the fictional transaction shows a separate fee.</td><td>Quiz using the earlier purchase</td></tr><tr><td>K</td><td>Keys (18)</td><td>Distinguish shareable information from a secret used to authorize action.</td><td>Quiz; no real keys</td></tr><tr><td>L</td><td>Ledger (19)</td><td>Compare the recorded 8-coin price with an altered 6-coin display.</td><td>Mini-game: record inspection</td></tr><tr><td>M</td><td>Mining &amp; Validators (20)</td><td>Compare two network roles without implying every chain uses both.</td><td>Mini-game: role comparison; later scope</td></tr><tr><td>N</td><td>NFTs (21)</td><td>Read what the lantern&#39;s ownership record says and what it does not prove.</td><td>Quiz using Lantern #014</td></tr><tr><td>O</td><td>On-Chain vs Off-Chain (22)</td><td>Decide which actions would change a shared record and which stay in an app.</td><td>Quiz</td></tr><tr><td>P</td><td>Proof Systems (23)</td><td>Compare simplified Proof of Work and Proof of Stake roles.</td><td>Quiz</td></tr><tr><td>S</td><td>Smart Contracts (26)</td><td>Predict whether a stated condition permits a fictional action.</td><td>Quiz; use existing purchase condition</td></tr><tr><td>T</td><td>Tokens (27)</td><td>Distinguish a recorded token from native coin and unique equipment.</td><td>Quiz</td></tr><tr><td>Y</td><td>Your Data and Privacy in Web3 (32)</td><td>Explain the privacy consequence of a public record.</td><td>Quiz</td></tr><tr><td>Z</td><td>Zero-Knowledge Proofs (33)</td><td>Recognize a claim verified without revealing the underlying detail.</td><td>Quiz; conceptual only</td></tr></tbody></table><h2 id="delivery-boundary-and-source-use">Delivery boundary and source use<a class="header-anchor" href="#delivery-boundary-and-source-use" aria-label="Link to this section">​</a></h2><ul><li><strong>Confirmed design direction:</strong> 26 letter lessons, split 13/13, with some mini-games and the rest quizzes. The precise world assignments and six proposed mini-game choices above are proposed for review.</li><li><strong>November 10 core:</strong> continue W01–W04 and B01–B03/demo B07 with contextual Quiz and reliable local saves. The C/W and B/L activities can draw on those existing actions; they do not require four new standalone games. R and M interactions remain later candidates.</li><li><strong>Full curriculum:</strong> author one age-appropriate objective, action or question, feedback explanation, and new-example check per letter. A quiz answer or mini-game completion alone does not prove learning.</li><li><strong>Supporting material:</strong> glossary page 35 can be split by concept (block/node/consensus with Blockchain; DApp/DAO/wallet/seed phrase with Web3). Safety pages 36–38 support Web3. Front matter and pages 39–43 provide context or attribution, not additional letter lessons. This book supplies no AI lesson curriculum.</li><li><strong>Accuracy check:</strong> the book&#39;s analogies are source material, not automatically final game copy. Avoid saying a blockchain record can never change, that a local hash proves historical truth, or that an NFT grants copyright or guaranteed value.</li></ul></div>',1)])])}const g=e(r,[["render",i]]);export{u as __pageData,g as default};
